'use strict';
window.classroomActive=false;window.classroomData=null;let schoolToken=sessionStorage.getItem('village-student-token')||'',schoolPending=false,schoolOnline=true,schoolQuiz='daily',schoolPoll=null;
const baseSchoolRender=render,baseSchoolPanel=renderPanel,baseSchoolSave=save,baseWeather=weather,baseMarket=marketOpen,baseBlocked=farmBlocked,baseQuiz=quiz;
const classroomBar=document.createElement('div');classroomBar.className='classroom-bar';classroomBar.hidden=true;document.querySelector('header').after(classroomBar);
const items=['상추','우유','사과','생선','당근','토마토','감자','딸기'];const symbols=['🥬','🥛','🍎','🐟','🥕','🍅','🥔','🍓'];const schoolTradeStock=i=>i<4?state.stock[i]:(state.garden?.stock?.[i-3]||0);
function requestId(){return Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')}
async function schoolFetch(route,data,token=schoolToken){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(route,{method:data?'POST':'GET',headers:{'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{})},...(data?{body:JSON.stringify(data)}:{}),signal:controller.signal,cache:'no-store'});const out=await r.json();if(!r.ok)throw Object.assign(new Error(out.error||'요청을 완료하지 못했어요.'),{status:r.status});return out}finally{clearTimeout(timer)}}
function applySchool(data){const current=window.classroomData;if(current?.me&&data.me?.id===current.me.id&&data.me.version<current.me.version)data={...data,me:current.me};if(current?.room?.id===data.room?.id&&data.room.version<current.room.version)data={...data,room:current.room};if(current?.room?.id===data.room?.id&&current.mission&&(!data.mission||current.mission.revision>data.mission.revision))data={...data,mission:current.mission};window.classroomData={...window.classroomData,...data};if(data.me){Object.assign(state,data.me.state);state.day=data.room.day;state.repaired=state.repairDay===data.room.day;state.harvest=state.productionDay===state.day?state.dailyProduction:0}schoolOnline=true;render()}
save=function(){if(!window.classroomActive)baseSchoolSave()};weather=function(){return window.classroomActive?weatherList[classroomData.room.weather]:baseWeather()};marketOpen=function(){return window.classroomActive?classroomData.room.market:baseMarket()};farmBlocked=function(){return window.classroomActive&&(classroomData.room.paused||!schoolOnline)||baseBlocked()};quiz=function(kind='daily'){schoolQuiz=kind;baseQuiz(kind)};
render=function(){baseSchoolRender();if(!window.classroomActive)return;const r=classroomData.room;classroomBar.hidden=false;classroomBar.innerHTML=`<b>학급 ${escapeHtml(r.code)} · ${escapeHtml(state.name)}</b><span>${escapeHtml(r.phase)} · ${r.paused?'수업 일시정지':'활동 중'}</span><span class="connection ${schoolOnline?'':'bad'}">${schoolPending?'저장 확인 중…':schoolOnline?'서버 연결됨':'연결 끊김 · 행동 잠금'}</span><button id="schoolReconnect">새로 확인</button><a class="school-link" href="teacher.html" target="_blank" rel="noopener">교사 화면</a>`;$('#schoolReconnect').onclick=refreshSchool;$('#nextDay').disabled=true;$('#nextDay').textContent='교사가 날짜 조절';$('#phaseDesc').textContent=`${r.paused?'교사가 수업을 일시정지했어요.':'학급과 함께 활동 중이에요.'} ${r.market?'장터가 열려 있어요.':'장터 개장을 기다려 주세요.'}`;$('#seasonBadge').textContent=r.phase;$('#reset').textContent='학급에서 나가기';document.querySelector('footer span:nth-child(2)').textContent='학급 공동 플레이 · 재고와 거래는 서버에 저장됩니다.'};
renderPanel=function(){if(!window.classroomActive){baseSchoolPanel();return}if(tab==='work'){baseSchoolPanel();const j=state.job;const div=document.createElement('div');div.className='school-prod';div.innerHTML=`<b>${symbols[j]} ${jobs[j].name}의 일</b><p>직업 생산은 하루 3회. 상추밭 재배와 별도로 내 생산물을 준비해요.</p><button class="wide" data-school-action="produce">${items[j]} 생산 · ${state.harvest}/3회</button>`;$('#panel').append(div);return}if(tab==='market'){const d=classroomData;$('#panel').innerHTML=`<span class="eyetag">우리 반 실제 장터</span><h2>${d.room.market?'장터가 열렸어요':'장터 개장 준비'}</h2><p>제안한 물건은 장터에 보관돼요. 상대가 수락하면 두 사람의 물건이 동시에 교환됩니다.</p><button class="primary wide" id="newSchoolOffer" ${!d.room.market?'disabled':''}>교환 제안 올리기</button>${d.offers.length?d.offers.map(o=>`<div class="school-offer"><b>${escapeHtml(o.seller_name)}</b><p>${symbols[o.give_item]} ${items[o.give_item]} ${o.give_qty}개 ↔ ${symbols[o.want_item]} ${items[o.want_item]} ${o.want_qty}개</p><button data-school-offer="${o.id}" data-offer-kind="${o.seller===d.me.id?'cancel':'accept'}" ${o.seller!==d.me.id&&!d.room.market?'disabled':''}>${o.seller===d.me.id?'내 제안 취소':'교환 내용 확인'}</button></div>`).join(''):'<p>아직 올라온 제안이 없어요. 첫 제안을 만들어 보세요.</p>'}`;$('#newSchoolOffer').onclick=newSchoolOffer;return}const r=classroomData.room;$('#panel').innerHTML=`<span class="eyetag">함께 차리는 식탁</span><h2>우리 반 공동 미션</h2><p>각 물건 ${r.goal}개를 함께 모아요. 기여한 물건은 활동 기록에 남아요.</p>${items.slice(0,4).map((n,i)=>`<div class="offer"><b>${symbols[i]} ${n} ${r.coop[i]}/${r.goal}</b><button data-school-donate="${i}" ${r.phase!=='협력'||state.stock[i]<1?'disabled':''}>1개 보태기</button></div>`).join('')}${r.coop.every(n=>n>=r.goal)?'<div class="notice">🎉 우리 반이 공동 식탁을 완성했어요!</div>':''}${weather().name.includes('폭우')&&!state.repaired?'<button class="wide secondary" data-action="repair">안전 복구 미션</button>':''}`};
async function schoolAction(payload){if(schoolPending){toast('앞선 저장을 확인 중이에요. 잠시만 기다려 주세요.');return false}if(!schoolOnline){toast('연결을 먼저 복구해 주세요.');return false}schoolPending=true;window.classroomSaving=true;payload.requestId=payload.requestId||requestId();sessionStorage.setItem('village-pending-command',JSON.stringify(payload));render();try{let result;for(let i=0;i<3;i++){try{result=await schoolFetch('/api/action',payload);break}catch(e){if(e.status)throw e;if(i===2)throw e;await new Promise(r=>setTimeout(r,500*(i+1)))}}sessionStorage.removeItem('village-pending-command');applySchool(result);return true}catch(e){if(e.status){sessionStorage.removeItem('village-pending-command');toast(e.message);try{applySchool(await schoolFetch('/api/state'))}catch{}}else{schoolOnline=false;toast('연결이 끊겼어요. 같은 요청으로 복구하므로 물건이 두 번 처리되지 않아요.')}return false}finally{schoolPending=false;window.classroomSaving=false;render()}}
async function refreshSchool(){if(!window.classroomActive||schoolPending)return;try{const pending=sessionStorage.getItem('village-pending-command');if(pending){schoolOnline=true;await schoolAction(JSON.parse(pending));return}applySchool(await schoolFetch('/api/state'))}catch(e){schoolOnline=false;if(e.status===401){schoolToken='';sessionStorage.removeItem('village-student-token');entrySchool()}render()}}
function entrySchool(){if($('#dialog').open)close();modal(`<span class="eyebrow">우리 반이 함께 만드는 마을</span><h2>Shiny Village에 오신 것을 환영해요</h2><p>농사를 짓고, 물건을 나누고, 함께 공부하며 서로 연결되는 마을이에요.</p><section class="trial-entry"><b>처음이라면, 코드 없이 둘러보세요</b><p>내 밭 → 수확 → 장터 교환·기부 → 별빛도서관<br>연습 친구가 있는 개인 체험 마을입니다. 실제 학생 기록과 섞이지 않아요.</p><button id="trialEntry" class="primary wide">🌱 체험 학생으로 시작</button></section><details><summary>학급 코드로 입장</summary><p>선생님이 나누어 준 학급 코드와 내 입장 코드를 입력하세요.</p><form id="schoolEntry" class="school-entry"><label>학급 코드<input id="roomCode" autocomplete="off" maxlength="6" required></label><label>학생 입장 코드<input id="studentCode" autocomplete="off" maxlength="48" required></label><p class="school-error" id="entryError"></p><button class="primary" type="submit">우리 반 입장</button></form></details><p id="trialError" role="status"></p><div class="dialog-actions"><button id="localDemo">농사만 혼자 연습</button><button id="teacherEntry">교사 화면</button></div>`);$('#trialEntry').onclick=async()=>{const button=$('#trialEntry');button.disabled=true;button.textContent='체험 마을에 입장 중…';$('#trialError').textContent='';try{let key=sessionStorage.getItem('village-trial-key');if(!key){key=requestId();sessionStorage.setItem('village-trial-key',key)}const data=await schoolFetch('/api/trial',{key},'');sessionStorage.removeItem('village-pending-command');schoolToken=data.token;sessionStorage.setItem('village-student-token',schoolToken);window.classroomActive=true;close();applySchool(data);startSchoolPolling()}catch(e){$('#trialError').textContent=e.status?e.message:'체험 서버 연결을 확인하지 못했어요. 다시 시도하거나 농사만 혼자 연습해 보세요.'}finally{button.disabled=false;button.textContent='🌱 체험 학생으로 시작'}};$('#schoolEntry').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('button');submit.disabled=true;try{const data=await schoolFetch('/api/join',{roomCode:$('#roomCode').value,code:$('#studentCode').value},'');if(data.teacher){$('#entryError').textContent='교사 코드는 교사 화면에서 사용해 주세요.';return}schoolToken=data.token;sessionStorage.setItem('village-student-token',schoolToken);window.classroomActive=true;close();applySchool(data);startSchoolPolling()}catch(error){$('#entryError').textContent=error.status?error.message:'서버 연결을 확인해 주세요. 혼자 연습하기는 사용할 수 있어요.'}finally{submit.disabled=false}};$('#localDemo').onclick=()=>{window.classroomActive=false;close();if(state.job===null)showJobs();else render()};$('#teacherEntry').onclick=()=>{location.href='teacher.html'}}
function newSchoolOffer(){modal(`<h2>교환 제안하기</h2><p>주는 물건은 수락 또는 취소 때까지 장터에 맡겨집니다.</p><div class="school-form"><select id="giveItem" aria-label="주는 물건">${items.map((n,i)=>`<option value="${i}">${n} · 보관 ${schoolTradeStock(i)}개</option>`).join('')}</select><input id="giveQty" type="number" min="1" max="50" value="2" aria-label="주는 수량"><select id="wantItem" aria-label="받는 물건">${items.map((n,i)=>`<option value="${i}" ${i===1?'selected':''}>${n}</option>`).join('')}</select><input id="wantQty" type="number" min="1" max="50" value="2" aria-label="받는 수량"></div><div class="dialog-actions"><button data-close>취소</button><button id="postSchoolOffer" class="primary">제안 올리기</button></div>`);$('#postSchoolOffer').onclick=async()=>{const ok=await schoolAction({action:'offer',giveItem:Number($('#giveItem').value),giveQty:Number($('#giveQty').value),wantItem:Number($('#wantItem').value),wantQty:Number($('#wantQty').value)});if(ok)close()}}
document.addEventListener('click',async e=>{if(!window.classroomActive)return;const b=e.target.closest('button');if(!b)return;let handled=true,payload=null;const plot=b.closest('[data-plot]');if(plot){const i=Number(plot.dataset.plot),stage=plotStage(state.farm.plots[i]);payload={action:stage===0?'plant':stage===1?'water':stage===4?'harvest':'',plot:i}}else if(b.id==='confirmFarmSell')payload={action:'sell',item:0,qty:Number($('#sellCount').value)};else if(b.id==='expandFarm'){const cost=state.farm.plots.length===6?40:state.farm.plots.length===8?60:80;modal(`<h2>밭 2칸을 넓힐까요?</h2><p>${cost}코인이 필요해요.</p><div class="dialog-actions"><button data-close>취소</button><button id="confirmSchoolExpand" class="primary">확장하기</button></div>`)}else if(b.id==='confirmSchoolExpand')payload={action:'expand'};else if(b.dataset.schoolAction)payload={action:b.dataset.schoolAction};else if(b.dataset.schoolDonate!==undefined)payload={action:'donate',item:Number(b.dataset.schoolDonate),qty:1};else if(b.dataset.schoolOffer){const id=b.dataset.schoolOffer,kind=b.dataset.offerKind;modal(`<h2>${kind==='cancel'?'제안을 취소할까요?':'이 교환을 수락할까요?'}</h2><p>${kind==='cancel'?'장터에 맡긴 물건이 돌아옵니다.':'상대가 맡긴 물건을 받고, 요청한 물건을 보내요.'}</p><div class="dialog-actions"><button data-close>돌아가기</button><button id="confirmSchoolTrade" class="primary">확정하기</button></div>`);$('#confirmSchoolTrade').onclick=async()=>{if(await schoolAction({action:kind,offer:id}))close()}}else if(b.dataset.answer!==undefined)payload={action:schoolQuiz==='repair'?'repair':'quiz',answer:Number(b.dataset.answer)};else if(b.dataset.action==='upgrade')payload={action:'upgrade'};else if(b.dataset.action==='harvest')payload={action:'produce'};else if(b.dataset.action==='sell')payload={action:'sell',item:state.job,qty:1};else if(b.id==='jobs'){modal(`<h2>내 역할 선택</h2><p>첫 생산 전에만 역할을 바꿀 수 있어요.</p>${jobs.map((j,i)=>`<button class="wide" data-school-job="${i}">${j.icon} ${j.name}</button>`).join('')}<button class="wide quiet" data-close>돌아가기</button>`)}else if(b.dataset.schoolJob!==undefined)payload={action:'job',job:Number(b.dataset.schoolJob)};else if(b.id==='reset'){sessionStorage.removeItem('village-student-token');sessionStorage.removeItem('village-pending-command');location.reload()}else if(b.id==='nextDay'){}else handled=false;
if(handled){e.preventDefault();e.stopImmediatePropagation();if(payload?.action){const ok=await schoolAction(payload);if(ok&&['sell','expand','quiz','repair','job'].includes(payload.action)&&$('#dialog').open)close()}return}if(b.dataset.tab){const place=b.dataset.tab;setTimeout(()=>schoolAction({action:'place',place}),0)}},true);
function startSchoolPolling(){clearInterval(schoolPoll);schoolPoll=setInterval(()=>{if(!document.hidden)refreshSchool()},10000+Math.random()*5000)}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&window.classroomActive)refreshSchool()});window.addEventListener('online',refreshSchool);window.addEventListener('offline',()=>{schoolOnline=false;if(window.classroomActive)render()});
if(schoolToken){window.classroomActive=false;schoolFetch('/api/state').then(data=>{window.classroomActive=true;close();applySchool(data);startSchoolPolling();if(sessionStorage.getItem('village-pending-command'))refreshSchool()}).catch(()=>{schoolToken='';entrySchool()}).finally(()=>window.villageBootReady?.('account'))}else{entrySchool();window.villageBootReady?.('account')};


// Keep the walkthrough available after entry and refresh, without interrupting play.
const trialGuide=document.createElement('details');trialGuide.className='trial-guide';trialGuide.hidden=true;trialGuide.open=localStorage.getItem('shiny-help-open')==='true';trialGuide.addEventListener('toggle',()=>localStorage.setItem('shiny-help-open',String(trialGuide.open)));
trialGuide.innerHTML='<summary>🌱 체험 마을 · 처음 시작하는 방법</summary><p>실제 학생이 아닌 <b>연습 친구</b>와 활동해요. 실제 학급 기록에는 반영되지 않아요.</p><ol><li><b>내 밭</b>에서 밭을 선택한 뒤 지도 아래의 심기·물 주기·수확 버튼을 눌러요.</li><li><b>장터</b>에서 연습 친구의 교환 제안을 수락해 보세요. 상추 1개로 우유나 사과를 받아요.</li><li><b>활동 → 공동 도시락</b>에서 수확물을 나누고, 메뉴의 <b>수입·기부 현황</b>에서 기록을 확인해요.</li><li>활동의 <b>진로 책장</b>에서 퀴즈를 풀고, <a href="campus.html#study">별빛도서관</a>에서 공부를 시작해 보세요.</li></ol><p>체험 마을은 장터와 협력이 열린 1일차예요. 실제 수업에서는 선생님이 날짜를 조절합니다. 메뉴의 내 정보·설정에서 로그아웃하면 학급 코드로 입장할 수 있어요.</p>';
document.querySelector('main').before(trialGuide);
const trialApplySchool=applySchool;applySchool=function(data){trialApplySchool(data);trialGuide.hidden=!data.me?.state?.trial;document.body.dataset.trial=String(!!data.me?.state?.trial)};
